        remaining: copyStock(stock),
        reason: 'invalid_lines',
      };
    }
    if (typeof line.sku !== 'string' || line.sku.length === 0) {
      return {
        accepted: false,
        remaining: copyStock(stock),
        reason: 'invalid_lines',
